namespace AgentOS.Domain.Planning;

public enum PlanningDraftStatus
{
    PendingReview = 0,
    Approved = 1,
    Rejected = 2
}

/// <summary>Human-reviewed task draft generated by the Planner agent (AOS-012).</summary>
public sealed class PlanningDraft
{
    public Guid Id { get; init; }

    public Guid? ProjectId { get; init; }

    public string Title { get; init; } = string.Empty;

    public string Goal { get; init; } = string.Empty;

    public string? Context { get; init; }

    public Guid? ModelProfileId { get; init; }

    public string? ModelProfileCode { get; init; }

    public PlanningDraftStatus Status { get; set; }

    public string ContentMarkdown { get; set; } = string.Empty;

    public string? ErrorMessage { get; set; }

    public DateTime CreatedAtUtc { get; init; }

    public DateTime UpdatedAtUtc { get; set; }

    public DateTime? DecidedAtUtc { get; set; }
}
